"""Pydantic schemas for AI verification endpoints."""
from pydantic import BaseModel, Field


class AITestRequest(BaseModel):
    """Schema for validating test prompts sent to the Gemini AI model."""
    prompt: str = Field(
        ...,
        min_length=3,
        max_length=2000,
        description="Text prompt to send to the Gemini AI model",
        examples=["Explain what a real estate lead is in one sentence."]
    )


class AITestResponse(BaseModel):
    """Schema for returning the text generated by the Gemini model."""
    response: str = Field(
        ...,
        description="Clean text generated by Gemini without SDK wrappers"
    )
